def recover_from_span(r_span, line1b):
    text=r_span["raw_span_bytes"].decode("utf-8")
    rlines=text.splitlines(True)
    idx=line1b-r_span["source_start"]
    if 0<=idx<len(rlines): return rlines[idx]
    return None

