        for r in reconstructed:
            if r["record_type"]=="MarkedVerbatimRegion" and r["source_start"]<=ln<=r["source_end"]:
                recovered=recover_from_span(r, ln); break
    elif reason=="TR-009_COVERED_BY_FENCE_CHILD":
